450	  memcpy (cur, bp->lines, bp->frames * 2 * sizeof(*cur));
451	  memmove (bp->lines, bp->lines + 2 * bp->frames,
452	           sizeof(*bp->lines) * (bp->count-1) * bp->frames * 2);
453	  memcpy (bp->lines + (bp->count-1) * bp->frames * 2, cur,
