458	  bp->heights[bp->count-1] = 0;
459	
460	  /* Regenerate the pair at the bottom. */
461	
462	  for (frame = 0; frame < bp->frames; frame++)
463	    {
464	      mi->polygon_count = 0;
465	      for (linesp = 0; linesp <= 1; linesp++)
466	        {
467	          int i;
