472	                   : wire ? GL_LINES : GL_QUAD_STRIP);
473	          for (i = 0; i < bp->resolution; i++)
474	            {
475	              GLfloat x = i / (GLfloat) bp->resolution;
476	              GLfloat z = (points[i] + frand (0.05)) * bp->amplitude;
477	
478	              if (bp->mask)
479	                {
480	                  int h = bp->mask->height;  /* leave a 10% gutter */
481	                  int y = bp->frame_count % (int) (h * 1.1);
482	                  unsigned long p = (y < h ? XGetPixel (bp->mask, i, y) : 0);
483	                  unsigned long gray = ((p >> 8) & 0xFF);
484	                  z *= gray * bp->mask_scale / 255.0;
485	                }
486	
487	              if (z < 0) z = 0;
488	              if (z > bp->amplitude) z = bp->amplitude;
489	              glVertex3f (x, 0, z);
490	              if (! linesp)
491	                glVertex3f (x, 0, 0);
492	              mi->polygon_count++;
493	            }
494	          glEnd ();
495	          glEndList ();
496	        }
497	    }
498	
499	  bp->frame_count++;
500	  mi->polygon_count *= bp->count;
501	  mi->polygon_count += 5;  /* base */
502	
503	  free (cur);
504	  free (points);
505	}
